def find_greater_lesser(numbers):
  if not numbers:
    return None, None
  greater = numbers[0]
  lesser = numbers[0]
  for number in numbers:
    if number > greater:
      greater = number
    if number < lesser:
      lesser = number
  return greater, lesser
