```python
import math

def standard_deviation(data):
    n = len(data)
    if n == 0:
        return 0
    mean = sum(data) / n
    variance = sum([(x - mean) ** 2 for x in data]) / n
    return math.sqrt(variance)
```

```python
def selection_sort(arr):
    n = len(arr)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        arr[i], arr[min_idx] = arr[min_idx], arr[i]
    return arr
```

