import hashlib
import time

def monitor_fraud(transactions, historical_data):
    alerts = []
    for transaction in transactions:
        hash_transaction = hashlib.sha256(str(transaction).encode()).hexdigest()
        if hash_transaction in historical_data:
            alerts.append(transaction)
        else:
            historical_data.add(hash_transaction)
    return alerts
